import os
from datetime import datetime, timedelta
from google.cloud import monitoring_v3
from google.cloud.monitoring_v3 import Aggregation
from google.api_core.exceptions import GoogleAPIError

def get_metric_statistics(
    metric_type: str,
    start_time: datetime,
    end_time: datetime,
    aggregation: str = "MEAN",
    alignment_period_seconds: int = 300,
    project_id: str = None
):
    """
    Retrieve aggregated statistics for a metric over a time window using Google Cloud Monitoring.

    Args:
        metric_type: The metric type (e.g., "compute.googleapis.com/instance/cpu/utilization").
        start_time: Start of the time window (datetime object).
        end_time: End of the time window (datetime object).
        aggregation: Aggregation function ("MEAN", "MAX", "MIN", "SUM", "COUNT").
        alignment_period_seconds: Alignment period in seconds.
        project_id: Google Cloud project ID. If None, uses environment default.

    Returns:
        List of dictionaries containing timestamp and aggregated value.
    """
    if project_id is None:
        project_id = os.getenv("GOOGLE_CLOUD_PROJECT")
        if not project_id:
            raise ValueError("Project ID must be provided or set via GOOGLE_CLOUD_PROJECT environment variable")

    client = monitoring_v3.MetricServiceClient()
    project_name = f"projects/{project_id}"

    aggregation_mapping = {
        "MEAN": Aggregation.Aligner.ALIGN_MEAN,
        "MAX": Aggregation.Aligner.ALIGN_MAX,
        "MIN": Aggregation.Aligner.ALIGN_MIN,
        "SUM": Aggregation.Aligner.ALIGN_SUM,
        "COUNT": Aggregation.Aligner.ALIGN_COUNT
    }

    if aggregation not in aggregation_mapping:
        raise ValueError(f"Unsupported aggregation: {aggregation}")

    interval = monitoring_v3.TimeInterval({
        "end_time": {"seconds": int(end_time.timestamp())},
        "start_time": {"seconds": int(start_time.timestamp())}
    })

    aggregation_obj = Aggregation({
        "alignment_period": {"seconds": alignment_period_seconds},
        "per_series_aligner": aggregation_mapping[aggregation]
    })

    try:
        results = client.list_time_series(
            request={
                "name": project_name,
                "filter": f'metric.type = "{metric_type}"',
                "interval": interval,
                "view": monitoring_v3.ListTimeSeriesRequest.TimeSeriesView.FULL,
                "aggregation": aggregation_obj
            }
        )

        data_points = []
        for series in results:
            for point in series.points:
                data_points.append({
                    "timestamp": datetime.fromtimestamp(point.interval.end_time.seconds),
                    "value": point.value.double_value or point.value.int64_value
                })

        return data_points

    except GoogleAPIError as e:
        raise RuntimeError(f"Google Cloud Monitoring API error: {e}")
